import json
import numpy as np,pandas as pd
from request_value import BASE,OLD
from update_calibration_experiment import hierarchical

def main():
 out=BASE/'results/purchase_matched_calibration';a=pd.read_csv(out/'outer_points.csv.gz');a=a[(~a.second_bought)&(a.relative>=.7)].copy();keys=['window_id','index'];fixed=pd.read_csv(BASE/'results/distance_nested_calibration/outer_points.csv.gz').query("model=='secant' and calibration=='pooled'").set_index(keys);assert not a.duplicated(keys).any();control=fixed.loc[pd.MultiIndex.from_frame(a[keys])].reset_index();assert len(control)==len(a);a['method']='skip_second';control['method']='buy_second';data=pd.concat([a,control]);sc=json.loads((OLD/'results/S0/fold_scales.json').read_text());data['nade']=data.error/np.array([sc[r.environment_id][r.dataset] for r in data.itertuples()]);metrics=['nade','coverage','width','pinball'];w=data.groupby(['method','window_id','dataset','environment_id','episode_uuid','side'],as_index=False)[metrics].mean();summary=hierarchical(w,['method'],metrics);summary.to_csv(out/'same_subset_summary.csv',index=False);env=w.groupby(['method','dataset','environment_id','episode_uuid','side'],as_index=False)[metrics].mean().groupby(['method','dataset','environment_id','episode_uuid'],as_index=False)[metrics].mean().groupby(['method','dataset','environment_id'],as_index=False)[metrics].mean();env.groupby(['method','dataset'],as_index=False)[metrics].mean().to_csv(out/'same_subset_sources.csv',index=False);audit=dict(passed=True,paired_points=len(a),paired_windows=a.window_id.nunique(),global_environments=a.environment_id.nunique(),source_environment_counts=a.groupby('dataset').environment_id.nunique().to_dict(),scope='same selected windows and nominal relative >=0.7 samples; own matched ranges for each strategy, posthoc subset not subgroup coverage guarantee');(out/'same_subset_audit.json').write_text(json.dumps(audit,indent=2),encoding='utf8');print(summary.to_string(index=False));print(json.dumps(audit))
if __name__=='__main__':main()
